import{_ as p,o as e,c as a,a0 as o}from"./chunks/framework.DqMqoJl9.js";const s=JSON.parse('{"title":"Math","description":"","frontmatter":{},"headers":[],"relativePath":"jsApi/Math/Math.md","filePath":"jsApi/Math/Math.md","lastUpdated":1791573371000}'),d={name:"jsApi/Math/Math.md"};function c(h,t,l,i,n,x){return e(),a("div",null,[...t[0]||(t[0]=[o('<p><a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/Math" target="_blank">原文链接</a><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Math" target="_blank">en</a></p><h1 id="math" tabindex="-1">Math <a class="header-anchor" href="#math" aria-label="Permalink to &quot;Math&quot;">​</a></h1><p>Math 是一个内置对象， 它具有数学常数和函数的属性和方法。不是一个函数对象。</p><h2 id="描述" tabindex="-1">描述 <a class="header-anchor" href="#描述" aria-label="Permalink to &quot;描述&quot;">​</a></h2><p>与其它全局对象不同的是, Math 不是一个构造器. Math 的所有属性和方法都是静态的. 你用到的常数pi可以用 Math.PI 表示,用 x 作 参数 Math.sin(x)调用sin函数. JavaScript中的常数, 是以全精度的实数定义的.</p><h2 id="属性" tabindex="-1">属性 <a class="header-anchor" href="#属性" aria-label="Permalink to &quot;属性&quot;">​</a></h2><p><code>Math.E</code></p><p>欧拉常数，也是自然对数的底数, 约等于 2.718</p><p><code>Math.LN2</code></p><p>2的自然对数, 约等于0.693</p><p><code>Math.LN10</code></p><p>10的自然对数, 约等于 2.303</p><p><code>Math.LOG2E</code></p><p>以2为底E的对数, 约等于 1.443</p><p><code>Math.LOG10E</code></p><p>以10为底E的对数, 约等于 0.434</p><p><code>Math.PI</code></p><p>圆周率，一个圆的周长和直径之比，约等于 3.14159</p><p><code>Math.SQRT1_2</code></p><p>1/2的平方根, 约等于 0.707</p><p><code>Math.SQRT2</code></p><p>2的平方根,约等于 1.414</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">注意</p><p>需要注意的是三角函数（sin(), cos(), tan(),asin(), acos(), atan(), atan2()）是以弧度返回值的。可以通过 除法（Math.PI / 180）把弧度转换为角度，也可以通过其他方法来转换。</p></div><div class="warning custom-block"><p class="custom-block-title">注意</p><p>需要注意的是很多数学函数都有一个精度，并且精度在不同环境下也是不相同的。这就意味着不同的浏览器会给出 不同的结果，甚至相同的 JS 引擎在不同的OS或者架构下也会给出不同的结果。</p></div><p><code>Math.abs(x)</code></p><p>返回x的绝对值</p><p><code>Math.acos(x)</code></p><p>返回x的反余弦值</p><p><code>Math.acosh(x)</code></p><p>返回x的反双曲余弦值</p><p><code>Math.asin(x)</code></p><p>返回x的反正弦值</p><p><code>Math.asinh(x)</code></p><p>返回x的反双曲正弦值</p><p><code>Math.atan(x)</code></p><p>以介于 -PI/2 与 PI/2 弧度之间的数值来返回 x 的反正切值</p><p><code>Math.atanh(x)</code></p><p>返回 x 的反双曲正切值</p><p><code>Math.atan2(x, y)</code></p><p>返回 y/x 的反正切值</p><p><code>Math.cbrt(x)</code></p><p>返回x的立方根</p><p><code>Math.ceil(x)</code></p><p>返回x向上取整后的值</p><p><code>Math.clz32(x)</code></p><p>返回一个数字在转换成 32 无符号整形数字的二进制形式后, 开头的 0 的个数</p><p><code>Math.cos(x)</code></p><p>返回x的余弦值</p><p><code>Math.cosh(x)</code></p><p>返回x的双曲余弦值</p><p><code>Math.exp(x)</code></p><p>返回 Ex, 当x为参数, E 是欧拉常数 (2.718...), 自然对数的底</p><p><code>Math.expm1(x)</code></p><p>返回 exp(x)-1 的值</p><p><code>Math.floor(x)</code></p><p>返回小于x的最大整数</p><p><code>Math.fround(x)</code></p><p>将任意的数字转换为离它最近的单精度浮点数形式的数字</p><p><code>Math.hypot([x[,y[,…]]])</code></p><p>返回它的所有参数的平方和的平方根</p><p><code>Math.imul(x)</code></p><p>返回两个参数的类C的32位整数乘法运算的运算结果</p><p><code>Math.log(x)</code></p><p>返回一个数的自然对数</p><p><code>Math.log1p(x)</code></p><p>返回一个数的自然对数</p><p><code>Math.log10(x)</code></p><p>返回一个数字以 10 为底的对数</p><p><code>Math.log2(x)</code></p><p>返回一个数字以 2 为底的对数</p><p><code>Math.max([x[,y[,…]]])</code></p><p>返回0个到多个数值中最大值</p><p><code>Math.min([x[,y[,…]]])</code></p><p>返回0个到多个数值中最小值</p><p><code>Math.pow(x,y)</code></p><p>返回x的y次幂</p><p><code>Math.random()</code></p><p>返回0到1之间的伪随机数</p><p><code>Math.round(x)</code></p><p>返回四舍五入后的整数</p><p><code>Math.sign(x)</code></p><p>返回x的符号函数, 判定x是正数,负数还是0</p><p><code>Math.sin(x)</code></p><p>返回正弦值</p><p><code>Math.sinh(x)</code></p><p>返回x的双曲正弦值</p><p><code>Math.sqrt(x)</code></p><p>返回x的平方根</p><p><code>Math.tan(x)</code></p><p>返回x的正切值</p><p><code>Math.tanh(x)</code></p><p>返回x的双曲正切值</p><p><code>Math.toSource()</code></p><p>返回字符串 &quot;Math&quot;</p><p><code>Math.trunc(x)</code></p><p>返回x的整数部分,去除小数</p><h2 id="规范" tabindex="-1">规范 <a class="header-anchor" href="#规范" aria-label="Permalink to &quot;规范&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Specification</th><th style="text-align:left;">Status</th><th style="text-align:left;">Comment</th></tr></thead><tbody><tr><td style="text-align:left;">ECMAScript 1rd Edition (ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;">Initial definition</td></tr><tr><td style="text-align:left;">ECMAScript 5.1 (ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">ECMAScript 2015 (6th Edition, ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;"></td></tr></tbody></table>',99)])])}const M=p(d,[["render",c]]);export{s as __pageData,M as default};
